function i(t){const r=Math.floor(t/60),e=t%60;return`${r}:${e.toString().padStart(2,"0")}`}function s(t,r,e){return r===0?"Perfect":((t+e)/r).toFixed(2)}function f(t){return t>=1e4?(t/1e4).toFixed(1)+"w":t>=1e3?(t/1e3).toFixed(1)+"k":t.toString()}function c(t){const r=new Date(t*1e3),e=(r.getMonth()+1).toString().padStart(2,"0"),n=r.getDate().toString().padStart(2,"0"),a=r.getHours().toString().padStart(2,"0"),o=r.getMinutes().toString().padStart(2,"0");return`${e}-${n} ${a}:${o}`}function u(t){const r=String(t).toUpperCase();return r.startsWith("S")?"#ffd700":r.startsWith("A")?"#4ecca3":r.startsWith("B")?"#4a9eff":r.startsWith("C")?"#a0a0a0":"#e94560"}const S={CLASSIC:"匹配/排位",ARAM:"大乱斗",URF:"无限火力",ONEFORALL:"克隆模式"};export{u as a,s as b,f as c,c as d,i as f,S as g};
